input.code:
import unreal
import json

selected_actors = unreal.EditorUtilityLibrary.get_selected_actors()

results = []
for actor in selected_actors:
    label = actor.get_actor_label()
    actor_class = actor.get_class().get_name()

    comps = actor.get_components_by_class(unreal.StaticMeshComponent)
    mat_info = []
    for comp in comps:
        num_mats = comp.get_num_materials()
        for i in range(num_mats):
            mat = comp.get_material(i)
            if mat:
                mat_info.append({
                    "slot": i,
                    "name": mat.get_name(),
                    "path": mat.get_path_name(),
                    "class": mat.get_class().get_name()
                })

    mesh_path = ""
    if comps:
        sm = comps[0].get_editor_property("static_mesh")
        if sm:
            mesh_path = sm.get_path_name()

    results.append({
        "label": label,
        "class": actor_class,
        "mesh": mesh_path,
        "materials": mat_info
    })

print(json.dumps(results, indent=2))
print(f"Total selected: {len(selected_actors)}")

